+        if (size >= capacity - 1) {
+            capacity *= 2;
+            char* new_buf = static_cast<char*>(realloc(buf, capacity));
+            if (!new_buf) {
+                free(buf);
+                raw_close(fd);
+                return nullptr;
+            }
+            buf = new_buf;
+        }
