+    if (!content) return -1;
+
+    int mem_fd = raw_memfd_create("filtered", 0);
+    if (mem_fd < 0) {
+        free(content);
+        return -1;
+    }
+
+    char* pos = content;
+    while (*pos) {
+        char* eol = strchr(pos, '\n');
+        size_t line_len;
+        if (eol) {
+            line_len = eol - pos + 1;
